import{_ as l,C as o,o as s,c as e,j as i,E as r,a as n,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"n":5,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":13,"title":"UI kit va dizayn tizimi tushunchasi","lead":"Bitta ilovaning 10 ta ekranida 10 xil ko'k tugma bo'lsa, foydalanuvchi buni darhol «tartibsizlik» deb sezadi. Katta kompaniyalar bu muammoni UI kit va dizayn tizimlari bilan hal qiladi. Bugun ular nima ekanini bilib olasiz va o'zingizning birinchi mini UI kitingizni yaratasiz.","link":"/mentor/9-sinf/hafta-05/dars-1","slide":"/slaydlar/9-sinf/hafta-05/dars-1.html","test":"/slaydlar/9-sinf/hafta-05/dars-1-test.html"},{"g":14,"title":"Mashhur UI kitlar: HIG, Ant Design, Bootstrap, Figma UI Kit, Material UI","lead":"iPhone ilovalari bir-biriga o'xshaydi, Google ilovalari ham — o'zaro. Sababi oddiy: ular bir xil UI kit va qoidalar asosida yaratilgan. Bugun dunyodagi 5 ta eng mashhur UI kit bilan tanishasiz va o'z loyihangiz uchun to'g'risini tanlashni o'rganasiz.","link":"/mentor/9-sinf/hafta-05/dars-2","slide":"/slaydlar/9-sinf/hafta-05/dars-2.html","test":"/slaydlar/9-sinf/hafta-05/dars-2-test.html"},{"g":15,"title":"UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli","lead":"Nazariya tugadi — endi qo'l ishi! Bugun Figma'da haqiqiy elektron kutubxona sahifasining eng muhim ikki qismini yasaysiz: qidiruvli header va kategoriyalar paneli. Har bir piksel, rang va burchak aniq qiymat bilan beriladi.","link":"/mentor/9-sinf/hafta-05/dars-3","slide":"/slaydlar/9-sinf/hafta-05/dars-3.html","test":"/slaydlar/9-sinf/hafta-05/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf/hafta-05/index.md","filePath":"mentor/9-sinf/hafta-05/index.md"}`),h={name:"mentor/9-sinf/hafta-05/index.md"},u={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},y={id:"baholash-mezoni",tabindex:"-1"};function k(b,a,_,c,f,v){const t=o("Icon");return s(),e("div",null,[i("div",u,[i("h2",g,[r(t,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–40 daqiqa. Barcha ishlarni bitta «E-kutubxona» Figma faylida (alohida sahifalarda) saqlang. Topshirish: keyingi dars boshida mentorga Figma havolasini (view huquqi bilan) ko&#39;rsating.</p><h2 id="_13-dars-uchun-ui-kit-va-dizayn-tizimi-tushunchasi" tabindex="-1">13-dars uchun (UI kit va dizayn tizimi tushunchasi) <a class="header-anchor" href="#_13-dars-uchun-ui-kit-va-dizayn-tizimi-tushunchasi" aria-label="Permalink to &quot;13-dars uchun (UI kit va dizayn tizimi tushunchasi)&quot;">​</a></h2><p><strong>1-topshiriq: «E-kutubxona UI kit sahifasi»</strong></p><ol><li>13-darsda boshlangan <code>UI Kit</code> sahifasini oching (Colors, Typography, Buttons).</li><li><strong>Inputs</strong> bo&#39;limini qo&#39;shing: oddiy (default), fokus (focus) va xato (error) holatidagi 3 ta matn maydoni (320 × 48, radius 8).</li><li>Barcha elementlarda faqat <strong>Color styles</strong> va <strong>Text styles</strong>&#39;dan foydalaning — HEX qiymatni qo&#39;lda yozmang.</li><li>Sahifa yon tomoniga token jadvalini matn sifatida yozing: 5 rang, 3 matn uslubi, 4 bo&#39;shliq (8, 16, 24, 32).</li></ol><p><strong>Kutiladigan natija:</strong> 4 bo&#39;limli (Colors, Typography, Buttons, Inputs) UI kit sahifasi va token jadvali; Primary rang o&#39;zgartirilganda tugma ham yangilanadi.</p><hr><h2 id="_14-dars-uchun-mashhur-ui-kitlar" tabindex="-1">14-dars uchun (Mashhur UI kitlar) <a class="header-anchor" href="#_14-dars-uchun-mashhur-ui-kitlar" aria-label="Permalink to &quot;14-dars uchun (Mashhur UI kitlar)&quot;">​</a></h2><p><strong>2-topshiriq: «Tayyor kitdan o&#39;rganamiz»</strong></p><ol><li>Figma <strong>Community</strong>&#39;dan bitta UI kitni oching (Material 3 Design Kit, iOS UI Kit, Ant Design yoki Bootstrap).</li><li>Undan 5 ta komponentni nusxalang: button, input, checkbox, card, navbar (yoki tabs).</li><li>Ularni «E-kutubxona» stillari (13-dars) bilan qayta bo&#39;yang.</li><li>3–4 jumlali izoh yozing: kit nimasi bilan yoqdi / yoqmadi, «E-kutubxona» uchun mosmi va nega.</li></ol><p><strong>Kutiladigan natija:</strong> <code>Kit tahlili</code> frame&#39;ida 5 ta qayta bo&#39;yalgan komponent va asoslangan izoh.</p><hr><h2 id="_15-dars-uchun-ui-kit-amaliyoti-header-va-kategoriya-paneli" tabindex="-1">15-dars uchun (UI kit amaliyoti: header va kategoriya paneli) <a class="header-anchor" href="#_15-dars-uchun-ui-kit-amaliyoti-header-va-kategoriya-paneli" aria-label="Permalink to &quot;15-dars uchun (UI kit amaliyoti: header va kategoriya paneli)&quot;">​</a></h2><p><strong>3-topshiriq: «E-kutubxona sahifasini to&#39;ldirish»</strong></p><ol><li>Darsda yaratilgan header va kategoriya paneliga asosiy menyu qo&#39;shing: «Bosh sahifa», «Yangi kitoblar», «Mualliflar», «Aloqa».</li><li>«Barcha kitoblar» tugmasini va kontent qismida banner joyini (Rectangle) qo&#39;shing.</li><li>Yagona uslub: bir xil ranglar (stillar), Inter shrifti, bir xil radius, 8-point grid oraliqlari; red guides bilan masofalarni tekshiring.</li><li>Qidiruv blokini (<code>Search/Default</code>) va tugmani komponentga aylantiring.</li></ol><p><strong>Kutiladigan natija:</strong> header, menyu, kategoriya paneli, tugma va banner joyidan iborat, yagona uslubdagi sahifa qismi; Assets&#39;da kamida 2 ta komponent.</p>',15))]),i("div",m,[i("h2",y,[r(t,{name:"list-checks"}),a[3]||(a[3]=n(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p>Guruhdagi har bir o&#39;quvchi uchun haftalik natijalar qaydnomasi.</p><p><strong>Guruh:</strong> 9-sinf (UX/UI dizayn va Advanced Front-end) <strong>Hafta:</strong> 5-hafta <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar" tabindex="-1">Shkala va mezonlar <a class="header-anchor" href="#shkala-va-mezonlar" aria-label="Permalink to &quot;Shkala va mezonlar&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Nazariy tushuncha (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq (Figma&#39;dagi UI kit va sahifa sifati)</td><td>30</td></tr><tr><td>Dizayn intizomi (Color/Text styles, aniq o&#39;lchamlar, teng oraliqlar, yagona uslub)</td><td>20</td></tr><tr><td>Uyga vazifa (o&#39;z vaqtida va to&#39;liq bajarilishi)</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>13-dars (UI kit) /100</th><th>14-dars (mashhur kitlar) /100</th><th>15-dars (E-kutubxona) /100</th><th>O&#39;rtacha ball</th><th>Hafta bahosi</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="darslar-bo-yicha-e-tibor-qaratiladigan-nuqtalar" tabindex="-1">Darslar bo&#39;yicha e&#39;tibor qaratiladigan nuqtalar <a class="header-anchor" href="#darslar-bo-yicha-e-tibor-qaratiladigan-nuqtalar" aria-label="Permalink to &quot;Darslar bo&#39;yicha e&#39;tibor qaratiladigan nuqtalar&quot;">​</a></h2><h3 id="_13-dars-ui-kit-va-dizayn-tizimi-tushunchasi" tabindex="-1">13-dars. UI kit va dizayn tizimi tushunchasi <a class="header-anchor" href="#_13-dars-ui-kit-va-dizayn-tizimi-tushunchasi" aria-label="Permalink to &quot;13-dars. UI kit va dizayn tizimi tushunchasi&quot;">​</a></h3><ul><li>UI Kit va dizayn tizimi farqini (UI Kit — tizimning bir qismi) to&#39;g&#39;ri tushuntirishi;</li><li>Dizayn tizimining 5 qismini va tokenlar mohiyatini bilishi;</li><li>Figma&#39;da Color va Text styles yaratib, tugmalarda faqat stillardan foydalanishi.</li></ul><h3 id="_14-dars-mashhur-ui-kitlar" tabindex="-1">14-dars. Mashhur UI kitlar <a class="header-anchor" href="#_14-dars-mashhur-ui-kitlar" aria-label="Permalink to &quot;14-dars. Mashhur UI kitlar&quot;">​</a></h3><ul><li>HIG, Ant Design, Bootstrap, Figma UI Kit va Material UI&#39;ning yaratuvchisi va asosini farqlashi;</li><li>Loyiha turiga qarab mos kitni tanlab, asoslay olishi;</li><li>Figma Community&#39;dagi kit komponentlarini mezonlar bo&#39;yicha taqqoslashi.</li></ul><h3 id="_15-dars-ui-kit-amaliyoti-«e-kutubxona»-header-va-kategoriya-paneli" tabindex="-1">15-dars. UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli <a class="header-anchor" href="#_15-dars-ui-kit-amaliyoti-«e-kutubxona»-header-va-kategoriya-paneli" aria-label="Permalink to &quot;15-dars. UI kit amaliyoti: «E-kutubxona» header va kategoriya paneli&quot;">​</a></h3><ul><li>W/H, X/Y, Corner radius (25), Fill → Image + Crop, Exposure sozlamalarini aniq qo&#39;llashi;</li><li>Stroke (Center/Inside), Drop shadow va red guides bilan tartibli panel yaratishi;</li><li>Barcha elementlarda yagona uslubni saqlab, qidiruv blokini komponentga aylantirishi.</li></ul><hr><p><strong>Mentor xulosasi va tavsiyalari:</strong> __________________________________________________</p>',18))])])}const z=l(h,[["render",k]]);export{p as __pageData,z as default};
